-- Fly-tipping 2023-24 and 2024-25: 678 rows (England and Wales)
-- written by scripts/import-fly-tipping.js --sql
\set ON_ERROR_STOP on
BEGIN;

CREATE TABLE public.council_fly_tipping_backup_20261019q AS SELECT * FROM public.council_fly_tipping WHERE year IN ('2023-24', '2024-25');
DELETE FROM public.council_fly_tipping WHERE year IN ('2023-24', '2024-25');

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.council_fly_tipping WHERE nation = 'England' AND year IN ('2023-24', '2024-25');
  IF n <> 634 THEN RAISE EXCEPTION 'expected 634 England rows, found %', n; END IF;
  SELECT count(*) INTO n FROM public.council_fly_tipping WHERE nation = 'Wales' AND year IN ('2023-24', '2024-25');
  IF n <> 44 THEN RAISE EXCEPTION 'expected 44 Wales rows, found %', n; END IF;
  SELECT count(*) INTO n FROM public.council_fly_tipping WHERE summed_from_districts;
  IF n <> 42 THEN RAISE EXCEPTION 'expected 42 county rows, found %', n; END IF;
  SELECT count(*) INTO n FROM public.council_fly_tipping f WHERE year IN ('2023-24', '2024-25') AND NOT EXISTS (SELECT 1 FROM public.councils c WHERE c.gss_code = f.gss);
  IF n <> 0 THEN RAISE EXCEPTION '% rows for councils not in councils', n; END IF;
END $$;

SELECT nation, year, count(*), count(incidents) AS with_incidents, sum(incidents) FILTER (WHERE NOT summed_from_districts) AS incidents FROM public.council_fly_tipping GROUP BY 1, 2 ORDER BY 1, 2;

COMMIT;
